#!/usr/bin/env node
// glob-select.js — deterministic glob path selector with decision receipts.
//
// API:  selectPaths(paths, patterns) -> {selected, decisions}
// CLI:  node glob-select.js INPUT_JSON_FILE

const ESCAPABLE = new Set(['\\', '*', '?', '[', ']', '!', '-']);

function fail(message) {
  throw new Error(message);
}

function isDenseArray(value) {
  return Array.isArray(value) &&
    Number.isInteger(value.length) &&
    value.length > 0 &&
    value.length === Object.keys(value).length;
}

function assertUnique(values, label) {
  const seen = new Set();
  for (const value of values) {
    if (seen.has(value)) fail(`${label} must be unique`);
    seen.add(value);
  }
}

function validatePaths(paths) {
  if (!isDenseArray(paths)) fail('paths must be a nonempty dense array');
  const seen = new Set();
  for (const path of paths) {
    if (typeof path !== 'string' || path.length === 0) {
      fail('paths must contain only nonempty strings');
    }
    if (path.includes('\u0000')) fail('paths must not contain NUL');
    if (path.startsWith('/') || path.endsWith('/')) {
      fail('paths must not start or end with /');
    }
    const segments = path.split('/');
    if (segments.some((s) => s === '' || s === '.' || s === '..')) {
      fail('paths must not contain empty, . or .. segments');
    }
    if (seen.has(path)) fail('paths must be unique');
    seen.add(path);
  }
}

function validatePatterns(patterns) {
  if (!isDenseArray(patterns)) fail('patterns must be a nonempty dense array');
  for (const pattern of patterns) {
    if (typeof pattern !== 'string' || pattern.length === 0) {
      fail('patterns must contain only nonempty strings');
    }
  }
}

// Parse one character class. Returns {end, test} where end is the index
// immediately after the closing ']'.
function parseClass(segment, start) {
  const chars = [];
  let negated = false;
  let i = start; // index just after '['
  if (i < segment.length && (segment[i] === '!' || segment[i] === '^')) {
    negated = true;
    i += 1;
  }
  if (i < segment.length && segment[i] === ']') chars.push(']'); // literal ]
  while (i < segment.length) {
    const ch = segment[i];
    if (ch === ']') return {end: i + 1, negated, chars};
    if (ch === '\\') {
      const next = segment[i + 1];
      if (next === undefined || !ESCAPABLE.has(next)) {
        fail('invalid escape inside character class');
      }
      chars.push(next);
      i += 2;
    } else if (ch === '-' && chars.length > 0 && i + 1 < segment.length) {
      const next = segment[i + 1];
      if (next === ']') {
        chars.push('-');
        i += 1;
      } else if (next === '\\') {
        const escaped = segment[i + 2];
        if (escaped === undefined || !ESCAPABLE.has(escaped)) {
          fail('invalid escape inside character class');
        }
        chars.push(chars.pop(), '-', escaped);
        i += 3;
      } else {
        chars.push(chars.pop(), '-', next);
        i += 2;
      }
    } else {
      chars.push(ch);
      i += 1;
    }
  }
  fail('unclosed [ in pattern');
}

function isRange(triple) {
  const a = triple[0];
  const c = triple[2];
  return a.length === 1 && c.length === 1 &&
    a.codePointAt(0) <= c.codePointAt(0);
}

// Parse one segment (no '/' characters) into an array of atom matchers.
function compileSegment(segment, index) {
  const atoms = [];
  let i = 0;
  while (i < segment.length) {
    const ch = segment[i];
    if (ch === '\\') {
      const next = segment[i + 1];
      if (next === undefined) fail('trailing lone backslash in pattern');
      if (next === '/' || !ESCAPABLE.has(next)) {
        fail('only \\, *, ?, [, ], !, - may be escaped');
      }
      atoms.push({literal: next});
      i += 2;
    } else if (ch === '?') {
      atoms.push({single: true});
      i += 1;
    } else if (ch === '*') {
      const run = segment.slice(i).match(/^\*+/)[0];
      atoms.push({star: run.length === 1});
      i += run.length;
    } else if (ch === '[') {
      const cls = parseClass(segment, i + 1);
      const items = cls.chars.slice();
      const test = (c) => {
        let found = false;
        for (let k = 0; k < items.length; k += 1) {
          const it = items[k];
          if (it === c) { found = true; break; }
          if (isRange(it) &&
              it[0] <= c && c <= it[2]) { found = true; break; }
        }
        return found;
      };
      atoms.push({class: {negated: cls.negated, test}});
      i = cls.end;
    } else {
      atoms.push({literal: ch});
      i += 1;
    }
  }
  return atoms;
}

function atomMatches(atom, ch) {
  if (atom.single) return true;
  if (atom.literal !== undefined) return ch === atom.literal;
  if (atom.class) return atom.class.negated ? !atom.class.test(ch) : atom.class.test(ch);
  return false; // star
}

function starAtom(atom, segment, i) {
  if (i === segment.length) return true;
  for (let k = i; k < segment.length; k += 1) {
    if (!atomMatches(atom, segment[k])) return false;
  }
  return true;
}

function matchAtoms(atoms, segment) {
  const n = atoms.length;
  const m = segment.length;
  let i = 0;
  let j = 0;
  let fallback = -1; // most recent star atom position with consumed j
  while (j < m) {
    if (i < n && atomMatches(atoms[i], segment[j])) {
      i += 1;
      j += 1;
    } else if (i < n && atoms[i].star) {
      if (i > fallback) fallback = i;
      i += 1; // star consumes nothing; re-consider atoms[i]
    } else if (fallback !== -1) {
      i = fallback; // back off to the star, which consumes one more char
      j += 1;
    } else {
      return false;
    }
  }
  // Only stars may match the empty remainder.
  while (i < n) {
    if (!atoms[i].star) return false;
    i += 1;
  }
  return true;
}

// Compile a pattern into per-segment atom lists. Double star (**) segments
// collapse to a single * segment; matching handles the zero-or-more-segment
// semantics.
function compilePattern(pattern) {
  return pattern.split('/').map((segment) => compileSegment(segment));
}

// segments: array of atom lists. pathSegments: actual path segments.
// Match segments 0..p-1, then require segments p..end to all be star lists
// (the collapsed ** behavior).
function matchFrom(segments, pathSegments, p) {
  const n = segments.length;
  for (; p < n; p += 1) {
    if (p < pathSegments.length) {
      if (!matchAtoms(segments[p], pathSegments[p])) return false;
    } else if (!starAtom(segments[p], '', 0)) {
      return false; // non-*** segment but no path segment left
    }
  }
  return p === pathSegments.length;
}

function matchSegments(segments, pathSegments) {
  const n = segments.length;
  if (n === 0) return pathSegments.length === 0;
  if (n === 1) return pathSegments.length === 1 && matchAtoms(segments[0], pathSegments[0]);
  if (matchFrom(segments, pathSegments, 1)) return true;
  // A ** segment (star-only list) may span zero or more whole path segments.
  for (let p = 1; p < n - 1; p += 1) {
    if (starAtom(segments[p], '', 0)) {
      for (let k = 0; k <= pathSegments.length; k += 1) {
        if (matchFrom(segments, pathSegments, p + k)) return true;
      }
    }
  }
  return false;
}

export function selectPaths(paths, patterns) {
  validatePaths(paths);
  validatePatterns(patterns);
  const compiled = patterns.map(compilePattern);
  const decisions = [];
  const selected = [];
  for (const path of paths) {
    const pathSegments = path.split('/');
    let included = false;
    let deciding = -1;
    for (let pi = 0; pi < compiled.length; pi += 1) {
      if (matchSegments(compiled[pi], pathSegments)) {
        included = patterns[pi].startsWith('!');
        deciding = pi;
      }
    }
    decisions.push({path, included, pattern: deciding});
    if (included) selected.push(path);
  }
  return {selected, decisions};
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

async function main() {
  const argv = process.argv.slice(2);
  if (argv.length !== 1) {
    process.stderr.write('usage: node glob-select.js INPUT_JSON_FILE\n');
    process.exitCode = 2;
    return;
  }
  let text;
  try {
    const {readFileSync} = await import('node:fs');
    text = readFileSync(argv[0], 'utf8');
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`);
    process.exitCode = 2;
    return;
  }
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    process.stderr.write(`error: invalid JSON: ${err.message}\n`);
    process.exitCode = 2;
    return;
  }
  if (!isPlainObject(data) ||
      !Array.isArray(data.paths) ||
      !Array.isArray(data.patterns)) {
    process.stderr.write('error: expected a JSON object with "paths" and "patterns" arrays\n');
    process.exitCode = 2;
    return;
  }
  let result;
  try {
    result = selectPaths(data.paths, data.patterns);
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`);
    process.exitCode = 2;
    return;
  }
  process.stdout.write(JSON.stringify(result) + '\n');
}

const isDirectRun = (() => {
  const entry = process.argv[1];
  if (!entry) return false;
  let current;
  let parent;
  try {
    current = new URL('file://' + entry);
    parent = import.meta.url;
  } catch {
    return false;
  }
  return current.href === parent;
})();

if (isDirectRun) main();

